<script lang="ts">
  import { onMount } from 'svelte';
  import { api, type Dataset, type Dashboard, type Supervised } from '$lib/api';
  import Chart from '$lib/Chart.svelte';
  let data = $state<Dashboard | null>(null);
  let dataset = $state<Dataset | null>(null);
  let error = $state('');
  let supervised = $state<Supervised | null>(null);
  let supervisedError = $state('');
  let representation = $state<'cleaned' | 'raw'>('cleaned');
  const classNames: Record<string,string> = { majority: 'Classe majoritária', ast_rules: 'Regras AST', logistic: 'TF-IDF + Regressão Logística', linearsvc: 'TF-IDF + LinearSVC', mlp: 'TF-IDF + MLP' };
  let supRows = $derived(supervised ? supervised.summary.filter(r => r.representation === representation && r.policy !== 'mlp') : []);
  let mlpSeeds = $derived(supervised ? supervised.summary.filter(r => r.representation === representation && r.policy === 'mlp') : []);
  let mlpAgg = $derived(supervised?.mlp?.across_seeds?.[representation] ?? null);
  let bestF1 = $derived(Math.max(0, ...supRows.map(r => r.metrics.f1_positive), mlpAgg?.metrics_mean?.f1_positive ?? 0));
  let mlpCwe = $derived(mlpSeeds.length ? Object.keys(mlpSeeds[0].by_cwe).map(cwe => [cwe, mlpSeeds.reduce((a, r) => a + r.by_cwe[cwe].f1_positive, 0) / mlpSeeds.length] as [string, number]) : []);
  let mlpFolds = $derived(supervised ? supervised.fold_selection.filter(f => f.policy === 'mlp' && f.representation === representation) : []);
  const pm = (k: 'precision' | 'recall' | 'f1_positive' | 'macro_f1' | 'balanced_accuracy') => mlpAgg?.metrics_mean ? `${num(mlpAgg.metrics_mean[k])} ± ${mlpAgg.metrics_std[k].toFixed(3).replace('.', ',')}` : '—';
  const num = (v: number) => v.toFixed(4).replace('.', ',');
  let seed = $state('42');
  let fold = $state('all');
  let cvRows = $derived(data ? (fold === 'all' ? data.cross_validation.pooled : data.cross_validation.experiments.filter(e => String(e.fold) === fold)).filter(e => String(e.seed) === seed) : []);
  const percent = (v: number | null) => v === null ? 'Não verificado' : `${(100*v).toFixed(1)}%`;
  const names: Record<string,string> = { random: 'Aleatório', rule_based: 'Regras fixas', q_learning: 'Q-Learning' };
  onMount(async () => { try { [data, dataset] = await Promise.all([api<Dashboard>('model/metrics'), api<Dataset>('dataset/info')]); seed = String(data.training.selected_seed); } catch(e) { error = String(e); }
    try { supervised = await api<Supervised>('model/supervised'); } catch(e) { supervisedError = String(e); } });
</script>
<section class="intro"><div><p class="eyebrow">02 / EVIDÊNCIA EXPERIMENTAL</p><h1>Aprendizado em números.<br/><span>Limites à vista.</span></h1><p class="lead">Três políticas, os mesmos exemplos de teste. Métricas calculadas a partir de execuções registradas.</p></div><aside class="scope"><span class="dot"></span> Experimento reproduzível<p>Validação de propriedades locais.<br/>Equivalência funcional não verificada.</p></aside></section>
{#if error}<p class="error" role="alert">{error}</p>{:else if !data || !dataset}<p class="notice" aria-live="polite">Carregando artefatos do experimento…</p>{:else}
  <div class="stats"><div><span>Dataset oficial</span><strong>{dataset.total.toLocaleString('pt-BR')}</strong><small>OWASP Benchmark Python {dataset.version}</small></div><div><span>Casos no escopo</span><strong>{dataset.selected}</strong><small>5 categorias CWE</small></div><div><span>Episódios por semente</span><strong>{data.training.runs[0].episodes.toLocaleString('pt-BR')}</strong><small>{data.training.runs.length} sementes independentes</small></div><div><span>Casos tratáveis no corpus</span><strong>{data.cross_validation.pooled[0]?.metrics.treatable}</strong><small>Antes: 5 · Agora: 3 transformações</small></div></div>
  <section class="panel"><div class="panel-heading"><h2>Validação cruzada por grupos · v2</h2><label>Partição <select bind:value={fold}><option value="all">Todos os folds (fora do treino)</option>{#each data.cross_validation.folds as f}<option value={String(f.fold)}>Fold {f.fold + 1}</option>{/each}</select></label></div>
    <p class="notice">{data.cross_validation.examples} exemplos · {data.cross_validation.groups} grupos · {data.cross_validation.folds.length} folds · 3 sementes. Cada caso aparece no teste uma vez por semente. Avaliação exploratória, sem confirmação independente. Hiperparâmetros mantidos; nenhum ajuste pelos testes externos.</p>
    <div class="table-scroll"><table><thead><tr><th>Política / semente {seed}</th><th>Casos</th><th>Correções / tratáveis</th><th>Correções / positivos</th><th>Alterações indevidas</th><th>Recompensa</th><th>Ações em estados não visitados</th></tr></thead><tbody>{#each cvRows as exp}<tr><td><strong>{names[exp.policy]}</strong></td><td>{exp.metrics.examples}</td><td>{exp.metrics.validated}/{exp.metrics.treatable} · {percent(exp.metrics.treatable_correction_rate)}</td><td>{percent(exp.metrics.validated_correction_rate)}</td><td>{percent(exp.metrics.unnecessary_change_rate)}</td><td>{exp.metrics.mean_reward.toFixed(3)}</td><td>{exp.policy === 'q_learning' ? exp.metrics.unseen_state_actions : 'Não se aplica'}</td></tr>{/each}</tbody></table></div>
    <details class="p-6"><summary>Distribuição das partições (total / tratáveis)</summary><div class="table-scroll"><table><thead><tr><th>Fold</th><th>Treino</th><th>Validação</th><th>Teste</th></tr></thead><tbody>{#each data.cross_validation.folds as f}<tr><td>{f.fold+1}</td><td>{f.train.count} / {f.train.treatable}</td><td>{f.validation.count} / {f.validation.treatable}</td><td>{f.test.count} / {f.test.treatable}</td></tr>{/each}</tbody></table></div></details>
  </section>
  <section class="panel mt-6"><div class="panel-heading"><h2>Classificação supervisionada · Lineares × MLP</h2><label>Representação <select bind:value={representation}><option value="cleaned">Código limpo</option><option value="raw">Código bruto</option></select></label></div>
    {#if supervisedError}<p class="error" role="alert">{supervisedError}</p>{:else if !supervised}<p class="notice">Carregando resultados supervisionados…</p>{:else}
    <p class="notice">Classificação binária por arquivo (vulnerável × não vulnerável), {supervised.examples} exemplos, {supervised.folds} folds por grupos, predições fora do treino. Seleção de hiperparâmetros por macro-F1 na validação interna; teste não usado na seleção. {#if supervised.mlp}MLP: comparação posterior aos resultados lineares, {supervised.mlp.seeds.length} semente(s) ({supervised.mlp.seeds.join('/')}), média ± desvio-padrão entre sementes; grid de {supervised.mlp.grid.length} configurações (64 neurônios ocultos; alpha {supervised.mlp.grid.map(g => g.alpha).join(' / ')}).{:else}Resultados do MLP indisponíveis: execute <code>training/supervised_mlp.py</code>.{/if}</p>
    <div class="table-scroll"><table><thead><tr><th>Modelo</th><th>Precision</th><th>Recall</th><th>F1 positivo</th><th>Macro-F1</th><th>Acurácia balanceada</th><th>FP</th><th>FN</th><th>F1 por fold</th></tr></thead><tbody>{#each supRows as r}<tr><td><strong>{classNames[r.policy] ?? r.policy}</strong>{#if r.metrics.f1_positive === bestF1 && bestF1 > 0} <span class="badge">Melhor F1</span>{/if}</td><td>{num(r.metrics.precision)}</td><td>{num(r.metrics.recall)}</td><td>{num(r.metrics.f1_positive)}</td><td>{num(r.metrics.macro_f1)}</td><td>{num(r.metrics.balanced_accuracy)}</td><td>{r.metrics.confusion.fp}</td><td>{r.metrics.confusion.fn}</td><td class="mono">{r.fold_f1.map(v => v.toFixed(2)).join(' · ')}</td></tr>{/each}{#if mlpAgg?.metrics_mean}<tr><td><strong>TF-IDF + MLP</strong> <small>(média de {mlpSeeds.length} sementes)</small>{#if mlpAgg.metrics_mean.f1_positive === bestF1} <span class="badge">Melhor F1</span>{/if}</td><td>{pm('precision')}</td><td>{pm('recall')}</td><td>{pm('f1_positive')}</td><td>{pm('macro_f1')}</td><td>{pm('balanced_accuracy')}</td><td>{mlpAgg.fp_mean.toFixed(1)}</td><td>{mlpAgg.fn_mean.toFixed(1)}</td><td class="mono">F1 por semente: {mlpAgg.f1_by_seed.map(v => v.toFixed(3)).join(' · ')}</td></tr>{/if}</tbody></table></div>
    {#if mlpSeeds.length}<details class="p-6"><summary>MLP por semente</summary><div class="table-scroll"><table><thead><tr><th>Semente</th><th>Precision</th><th>Recall</th><th>F1 positivo</th><th>FP</th><th>FN</th><th>F1 por fold</th></tr></thead><tbody>{#each mlpSeeds as r}<tr><td>{r.seed}</td><td>{num(r.metrics.precision)}</td><td>{num(r.metrics.recall)}</td><td>{num(r.metrics.f1_positive)}</td><td>{r.metrics.confusion.fp}</td><td>{r.metrics.confusion.fn}</td><td class="mono">{r.fold_f1.map(v => v.toFixed(2)).join(' · ')}</td></tr>{/each}</tbody></table></div></details>{/if}
    <div class="p-6 space-y-6"><h3>F1 positivo por CWE</h3>{#each supRows.filter(r => ['linearsvc','logistic','ast_rules'].includes(r.policy)) as r}<div><h3>{classNames[r.policy] ?? r.policy}</h3>{#each Object.entries(r.by_cwe) as [cwe,m]}<div class="bar-row"><span>CWE-{cwe}</span><div class="bar-track"><div style={`width:${m.f1_positive*100}%`}></div></div><span>{m.f1_positive.toFixed(2)}</span></div>{/each}</div>{/each}{#if mlpCwe.length}<div><h3>TF-IDF + MLP (média de {mlpSeeds.length} sementes)</h3>{#each mlpCwe as [cwe,f1]}<div class="bar-row"><span>CWE-{cwe}</span><div class="bar-track"><div style={`width:${f1*100}%`}></div></div><span>{f1.toFixed(2)}</span></div>{/each}</div>{/if}</div>
    {#if mlpFolds.length}<details class="p-6"><summary>Configuração do MLP escolhida em cada fold</summary><div class="table-scroll"><table><thead><tr><th>Semente</th><th>Fold</th><th>Camadas ocultas</th><th>alpha</th><th>Macro-F1 validação</th><th>F1 teste</th><th>Convergiu</th></tr></thead><tbody>{#each mlpFolds as f}<tr><td>{f.seed}</td><td>{f.fold+1}</td><td>{JSON.stringify(f.selection.hidden_layer_sizes)}</td><td>{f.selection.alpha}</td><td>{num(Number(f.selection.validation_macro_f1))}</td><td>{num(f.metrics.f1_positive)}</td><td>{f.converged ? 'Sim' : 'Não (limite de iterações)'}</td></tr>{/each}</tbody></table></div></details>{/if}
    <p class="notice">Corpus já inspecionado: avaliação exploratória, sem validação externa. F1 de classificação não é comparável à taxa de correção do Q-Learning. A aplicação continua servindo o LinearSVC.</p>
    {/if}
  </section>
  <div class="section-heading"><h2>Treinamento do modelo demonstrativo</h2><label>Semente <select bind:value={seed}>{#each data.training.runs as run}<option value={String(run.seed)}>{run.seed}</option>{/each}</select></label></div>
  <section class="panel"><Chart rows={data.curves[seed] || []} metric="reward" title="Recompensa média · janela de 100 episódios"/><div class="grid md:grid-cols-2"><Chart rows={data.curves[seed] || []} metric="epsilon" title="Exploração · epsilon"/><Chart rows={data.curves[seed] || []} metric="validated" title="Episódios com correção validada · janela de 100"/></div></section>
  <section class="panel mt-6"><div class="panel-heading"><h2>Comparação no conjunto de teste demonstrativo</h2><span class="badge">Semente {seed}</span></div><div class="table-scroll"><table><thead><tr><th>Política</th><th>Correções / positivos</th><th>Correções / tratáveis</th><th>Alterações indevidas</th><th>Ações médias</th><th>Recompensa média</th></tr></thead><tbody>{#each data.evaluation.experiments.filter(e => String(e.seed) === seed) as exp}<tr><td><strong>{names[exp.policy]}</strong></td><td>{percent(exp.metrics.validated_correction_rate)} ({exp.metrics.validated}/{exp.metrics.positives})</td><td>{percent(exp.metrics.treatable_correction_rate)}</td><td>{percent(exp.metrics.unnecessary_change_rate)}</td><td>{exp.metrics.mean_actions.toFixed(2)}</td><td>{exp.metrics.mean_reward.toFixed(2)}</td></tr>{/each}</tbody></table></div><p class="notice">Regressões funcionais e sucesso completo: não verificados. A correção validada atesta somente a propriedade local modificada. Este holdout é secundário; a avaliação principal usa os quatro folds acima.</p></section>
  <div class="grid lg:grid-cols-2 gap-6 mt-6"><section class="panel"><div class="panel-heading"><h2>Correções por categoria</h2></div><div class="p-6 space-y-6">{#each cvRows as exp}<div><h3>{names[exp.policy]}</h3>{#each Object.entries(exp.by_cwe) as [cwe,m]}<div class="bar-row"><span>CWE-{cwe}</span><div class="bar-track"><div style={`width:${(m.validated_correction_rate || 0)*100}%`}></div></div><span>{m.validated}/{m.positives}</span></div>{/each}</div>{/each}</div></section>
  <section class="panel"><div class="panel-heading"><h2>Distribuição das ações</h2></div><div class="p-6 space-y-6">{#each cvRows as exp}<div><h3>{names[exp.policy]}</h3>{#each Object.entries(exp.metrics.actions) as [action,count]}<div class="action-row"><code>{action}</code><span>{count}</span></div>{/each}</div>{/each}</div></section></div>
  <section class="panel mt-6"><div class="panel-heading"><h2>Origem e protocolo</h2><a href="https://github.com/OWASP-Benchmark/BenchmarkPython">Repositório OWASP ↗</a></div><div class="p-6"><p>{dataset.dataset} · versão {dataset.version}</p><p class="mono break-all">Commit: {dataset.commit}</p><p class="mt-3">Modelo demonstrativo — Treinamento: {dataset.splits.train.count} · Validação: {dataset.splits.validation.count} · Teste: {dataset.splits.test.count}</p><p class="notice">Agrupamento heurístico por AST do fluxo. Não comprova ausência de toda similaridade. O escopo pequeno não sustenta generalização para reparo de código em produção.</p><details><summary>Distribuição original por CWE e rótulo</summary><div class="distribution">{#each Object.entries(dataset.distribution) as [key,count]}<div><span>{key}</span><strong>{count}</strong></div>{/each}</div></details><details><summary>Hiperparâmetros e recompensas</summary><pre>{JSON.stringify(data.training.runs[0].config, null, 2)}</pre></details></div></section>
{/if}
